const projects = $input.all().map(i => i.json);
const today = new Date();
const alerts = [];

for (const p of projects) {
  if (!p.deadline || p.status !== 'active') continue;

  const deadline = new Date(p.deadline);
  const daysLeft = Math.ceil((deadline - today) / (1000 * 60 * 60 * 24));

  if ([14, 7, 1].includes(daysLeft)) {
    const urgency = daysLeft === 1 ? '🚨 URGENT' : daysLeft === 7 ? '⚠️ WARNING' : '📅 REMINDER';
    alerts.push({
      project: p.name,
      customer: p.customer,
      daysLeft,
      deadline: p.deadline,
      value: p.value_eur ? `€${(p.value_eur/1e6).toFixed(1)}M` : 'TBD',
      projectId: p.id,
      urgency,
      message: `${urgency} — ${p.name}\n*Customer:* ${p.customer}\n*Deadline:* ${p.deadline} (${daysLeft} day${daysLeft === 1 ? '' : 's'} left)\n*Value:* ${p.value_eur ? '€' + (p.value_eur/1e6).toFixed(1) + 'M' : 'TBD'}\n<http://localhost:5173/rfq?project=${p.id}|Open project →>`
    });
  }
}

if (alerts.length === 0) {
  return [{ json: { skip: true, message: 'No deadlines today' } }];
}

return alerts.map(a => ({ json: a }));

// Log that no deadlines need alerting today
console.log('No deadline alerts today:', new Date().toISOString());
return [{ json: { status: 'no_alerts', timestamp: new Date().toISOString() } }];

// In production: send to Slack/email here
// For now: log the alert
const alert = $input.first().json;
console.log('DEADLINE ALERT:', alert.message);
return [{ json: { status: 'alert_sent', project: alert.project, daysLeft: alert.daysLeft } }];
